<script setup lang="ts">
import {onMounted,ref} from 'vue';import P6Dialog from './P6Dialog.vue';import './p6.css';type Row=Record<string,any>;const props=defineProps<{request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>}>();const rows=ref<Row[]>([]),editing=ref<Row|null>(null),busy=ref(false),error=ref('');
async function load(){rows.value=(await props.request<Row>('/platform/p7/plans')).items;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function edit(row:Row){editing.value={...row,expectedVersion:row.version};}async function save(){await props.request('/platform/p7/plans/'+editing.value!.id,'PUT',editing.value);editing.value=null;await load();}onMounted(()=>run(load));
</script>
<template><section class="p6"><div class="page-heading"><div><span class="eyebrow">PLATFORM CAPABILITIES</span><h1>扩展功能套餐</h1><p>为企业套餐配置自动化、业务扩展、外链表单和迁移额度。</p></div><button class="btn secondary" :disabled="busy" @click="run(load)">刷新</button></div><p v-if="error" class="p6-error" role="alert">{{error}}</p><div class="p6-card p7-plan-scroll"><table><thead><tr><th>套餐</th><th>自动化</th><th>业务扩展与表单</th><th>迁移</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.name}}</td><td>{{row.automationEnabled?'已启用':'未启用'}}<small>{{row.automationRuleLimit}} 条规则 / {{row.automationMonthlyLimit}} 次月执行</small></td><td>{{row.workspaceEnabled?'已启用':'未启用'}}<small>{{row.publicFormLimit}} 个有效表单 / {{row.publicSubmissionMonthlyLimit}} 次月提交</small></td><td>{{row.migrationEnabled?'已启用':'未启用'}}<small>每月 {{row.migrationMonthlyRowLimit}} 行</small></td><td><button class="text-button" :disabled="busy" @click="edit(row)">配置</button></td></tr></tbody></table></div><P6Dialog v-if="editing" :title="'配置套餐 · '+editing.name" :busy="busy" @close="!busy&&(editing=null)"><p v-if="error" class="p6-error">{{error}}</p><form @submit.prevent="run(save)"><fieldset :disabled="busy"><label class="p7-plan-check"><input v-model="editing.automationEnabled" type="checkbox"/>启用自动化</label><div class="p6-grid"><label>规则数量上限<input v-model.number="editing.automationRuleLimit" type="number" min="0" max="1000" required/></label><label>每月执行上限<input v-model.number="editing.automationMonthlyLimit" type="number" min="0" max="1000000" required/></label></div><label class="p7-plan-check"><input v-model="editing.workspaceEnabled" type="checkbox"/>启用业务扩展与外链表单</label><div class="p6-grid"><label>有效表单上限<input v-model.number="editing.publicFormLimit" type="number" min="0" max="1000" required/></label><label>每月表单提交上限<input v-model.number="editing.publicSubmissionMonthlyLimit" type="number" min="0" max="1000000" required/></label></div><label class="p7-plan-check"><input v-model="editing.migrationEnabled" type="checkbox"/>启用数据迁移</label><label>每月迁移行数上限<input v-model.number="editing.migrationMonthlyRowLimit" type="number" min="0" max="1000000" required/></label></fieldset><button class="btn primary" :disabled="busy">保存套餐配置</button></form></P6Dialog></section></template>
<style scoped>.p7-plan-scroll{overflow:auto}.p7-plan-scroll th{background:#20324f;color:#bdd1ec}.p7-plan-scroll td{background:#14223b;color:#e0ebfa}.p7-plan-check{flex-direction:row;align-items:center}.p7-plan-check input{width:18px;height:18px}</style>
